print("Character-by-character analysis:")
for i, (inp, outp) in enumerate(zip(inputs, outputs)):
    print(f"\n{i+1}. '{inp}' -> '{outp}':")
    min_len = min(len(inp), len(outp))
    for j in range(max(len(inp), len(outp))):
        if j >= len(inp):
            print(f"   Pos {j}: added '{outp[j]}'")
        elif j >= len(outp):
            print(f"   Pos {j}: removed '{inp[j]}'")
        elif inp[j] != outp[j]:
            print(f"   Pos {j}: '{inp[j]}' -> '{outp[j]}'")
        else:
            print(f"   Pos {j}: '{inp[j]}' -> '{outp[j]}' (same)")

